bin/price.text:
#!/bin/bash
# Member price in cents: 10% off, rounded down.
echo $(( $1 * 90 / 100 ))

bin/quote.text:
#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( $1 * 90 / 100 ))"

lib/invoice.sh.text:
#!/bin/bash
# Invoice line for a member order.
echo "member total $(( $1 * 90 / 100 ))"

lib/receipt.sh.text:
#!/bin/bash
# Receipt line for a member order.
echo "receipt $(( $1 * 9 / 10 ))"

arguments.command:
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
# PRC-305: 10% off, rounded DOWN. 999*0.9 = 899.1 -> 899
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash -c 'source lib/invoice.sh' _ 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
[ "$(bash lib/receipt.sh 999)" = "receipt 899" ] || { echo "receipt 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh

